function canIWin(maxChoosableInteger, desiredTotal) {
  if (desiredTotal <= 0) return true;
  const sum = maxChoosableInteger * (maxChoosableInteger + 1) / 2;
  if (sum < desiredTotal) return false;
  // memo[used]: 0 = not solved yet, 1 = the player to move wins, 2 = the player to move loses.
  const memo = new Int8Array(1 << maxChoosableInteger);
  const canWin = (used, remaining) => {
    if (memo[used] !== 0) return memo[used] === 1;
    for (let pick = maxChoosableInteger; pick >= 1; pick--) {
      const bit = 1 << (pick - 1);
      if ((used & bit) !== 0) continue;
      if (pick >= remaining || !canWin(used | bit, remaining - pick)) {
        memo[used] = 1;
        return true;
      }
    }
    memo[used] = 2;
    return false;
  };
  return canWin(0, desiredTotal);
}

