function canIWin(maxChoosableInteger, desiredTotal) {
  if (desiredTotal === 0) return true;
  // Plain minimax over the remaining pool: +1 the mover wins, 0 nobody wins, -1 the mover loses.
  const pool = Array.from({ length: maxChoosableInteger }, (_, i) => i + 1);
  if (pool.reduce((a, b) => a + b, 0) < desiredTotal) return false;
  const value = (left, total) => {
    let best = left.length === 0 ? 0 : -1;
    for (let i = 0; i < left.length; i++) {
      const score = total + left[i] >= desiredTotal ? 1 : -value(left.filter((_, j) => j !== i), total + left[i]);
      if (score > best) best = score;
      if (best === 1) break;
    }
    return best;
  };
  return value(pool, 0) === 1;
}

