function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const max = size === 'large' ? 16 + pick(5) : 1 + pick(8);
  const sum = max * (max + 1) / 2;
  // Totals cluster around the interesting range (up to the pool's sum), with a few beyond it and a few at 0.
  const roll = rand();
  const total = roll < 0.08 ? 0 : roll < 0.16 ? Math.min(300, sum + 1 + pick(10)) : 1 + pick(Math.min(300, sum));
  return [max, total];
}
